// The two Coast Commons studies (/coast-commons/sb-surf-house/, /coast-commons/fresh-milk/): static pages
// generated by scripts/coast-commons-studies/build.mjs. These checks keep the pages, the hub entry,
// the registrations and the rules for publishing them in step.
import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { NOTICE } from '../scripts/coast-commons-studies/build.mjs';
import { SOURCES as SURF } from '../scripts/coast-commons-studies/surf-house.sources.mjs';
import { SOURCES as MILK } from '../scripts/coast-commons-studies/fresh-milk.sources.mjs';

const root = new URL('../', import.meta.url);
const read = (p) => readFileSync(new URL(p, root), 'utf8');
const slugs = ['sb-surf-house', 'fresh-milk'];
const page = Object.fromEntries(slugs.map((s) => [s, read(`public/coast-commons/${s}/index.html`)]));
const surf = page['sb-surf-house'];
const milk = page['fresh-milk'];
const twin = JSON.parse(read('public/coast-commons.json'));
const hub = read('public/coast-commons/index.html');
const text = (h) => h.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/g, ' ').replace(/<[^>]+>/g, ' ');

test('the committed pages match the generator, and so does the hub that lists them', () => {
  execFileSync(process.execPath, [fileURLToPath(new URL('scripts/coast-commons-studies/build.mjs', root)), '--check'], { stdio: 'pipe' });
  execFileSync(process.execPath, [fileURLToPath(new URL('scripts/coast-commons/build.mjs', root)), '--check'], { stdio: 'pipe' });
});

test('the plain box opens each page with every line', () => {
  for (const s of slugs) {
    const h = page[s];
    const box = h.match(/<aside class="plain"[\s\S]*?<\/aside>/);
    assert.ok(box, `${s} has the plain box`);
    for (const line of NOTICE) assert.ok(box[0].includes(line), `${s}: ${line}`);
    for (const line of ['It is not an offer.', 'Nothing is being bought or sold. No money is being raised.', 'not legal, tax, health or investment advice', 'likely securities', 'securities lawyer', 'Distributing milk from unlicensed animals is unlawful in California']) assert.ok(box[0].includes(line), `${s}: ${line}`);
    assert.ok(h.indexOf('<aside class="plain"') < h.indexOf('<section'), `${s}: the box comes before the first section`);
    assert.match(box[0], /Written by Claude/);
  }
});

test('every source is a link beside a claim, dated, and counted on the hub', () => {
  for (const [, , , url] of SURF) assert.ok(surf.split(`href="${url.replace(/&/g, '&amp;')}"`).length >= 3, `surf house cites and lists ${url}`);
  for (const [, url] of MILK) assert.ok(milk.includes(url), `milk links ${url}`);
  for (const row of [...SURF.map((r) => r[3]), ...MILK.map((r) => r[1])]) assert.match(row, /^https:\/\//);
  const asof = (surf.match(/class="asof">As of Nov 11, 2026/g) || []).length;
  assert.ok(asof >= 9, `surf house dates its sourced sections (${asof})`);
  const checked = (milk.match(/class="checked">[^<]*Nov 11, 2026/g) || []).length;
  assert.ok(checked >= 8, `milk dates its sections (${checked})`);
  const list = Object.fromEntries(twin.studies.list.map((x) => [x.slug, x]));
  assert.equal(list['sb-surf-house'].source_count, SURF.length);
  assert.equal(list['fresh-milk'].source_count, MILK.length);
  for (const s of slugs) { assert.equal(list[s].verified, '2026-11-11'); assert.ok(list[s].not_verified.length >= 8); }
});

test('what was not verified is said beside the claim, not only in the limits list', () => {
  // "Beside" means inside the same card, list item or paragraph pair as the claim.
  const near = (h, anchor, re, end) => {
    const i = h.indexOf(anchor); assert.ok(i > -1, anchor);
    const j = h.indexOf(end, i + anchor.length); assert.ok(j > -1, `${anchor} ends`);
    assert.match(h.slice(i, j), re, anchor);
  };
  near(surf, '<h3>City of Santa Barbara</h3>', /class="nv">Not verified against the ordinance text/, '<div class="card');
  near(surf, '<h3>Santa Barbara County, including Isla Vista</h3>', /class="nv">Not verified on the County's own ordinance page/, '<div class="card');
  near(surf, '<h3>Carpinteria</h3>', /class="nv">The four cap numbers are not verified/, '<div class="card');
  near(surf, '<h3>The family beach town</h3>', /class="nv">Read on a third-party copy/, '</div>');
  near(surf, 'replaced on March 17, 2026', /class="nv">Not verified against the release itself/, '<h3>');
  assert.match(surf, />County page \(did not load, not read\)</);
  near(milk, '<b>Local zoning</b>', /class="nv">Not verified: the animal codes of El Segundo, Manhattan Beach and Redondo Beach/, '</li>');
  for (const town of ['El Segundo', 'Manhattan Beach', 'Redondo Beach']) assert.match(milk, new RegExp(`\\["${town}","[^"]+",P\\.no,`), `${town} is marked Not verified in the table`);
  near(milk, "<strong>Broguiere's, Montebello.</strong>", /class="nv">Status in 2026: not verified/, '</li>');
  near(milk, '<strong>A goat dairy in Ontario, San Bernardino County.</strong>', /class="nv">Status in 2026, and whether it moved: not verified/, '</li>');
  near(milk, '<strong>An urban farm in Compton.</strong>', /class="nv">Whether it still runs these programs in 2026: not verified/, '</li>');
  near(milk, '<strong>Home delivery routes.</strong>', /not verified/, '</li>');
  near(milk, '<b>What was found nearby</b>', /class="nv">Not verified for 2026/, '</li>');
});

test('publishing rules: no listings, no health claims for milk, unnamed businesses unless linked to their own site', () => {
  const banned = /good ?feels|cannabis|\bhemp\b|\bthc\b|redfin|airbnb|vrbo|for sale by|buy now|invest now|guaranteed|\broi\b|\bbrief asks\b/i;
  for (const s of slugs) { const hit = text(page[s]).match(banned); assert.equal(hit, null, `${s}: ${hit && hit[0]}`); }
  assert.match(surf, /No listing is quoted/);
  assert.doesNotMatch(surf, /\d{2,5} [A-Z][a-z]+ (Street|St\.|Avenue|Ave\.|Drive|Road|Lane)\b/, 'no street addresses');
  // Named in the private drafts, described without a name in public: only a news report was read for each.
  const unnamed = /RealT|CityDAO|LinksDAO|Spey Bay|Pacaso|Ooki|Moonwater|Drake Family|Alta Dena|Stroud Micro Dairy|Norwich Farm/;
  for (const s of slugs) assert.doesNotMatch(text(page[s]), unnamed, `${s} names a business it does not link`);
  assert.ok(milk.includes('href="https://www.broguieresmilk.com/"'), 'the one named dairy links its own site');
  assert.match(milk, /No health-benefit claims are made on this page/);
  assert.doesNotMatch(text(milk), /\b(healthier|more nutritious|boosts?|cures?|probiotic|immune-boosting|good for you)\b/i);
  assert.match(surf, /SCHEMATIC · NOT A BLUEPRINT · NOT FOR CONSTRUCTION/);
  assert.equal((surf.match(/Illustrative only/g) || []).length, 1);
  assert.match(milk, /Illustrative only/);
});

test('each page is self-contained and bylined to Claude', () => {
  for (const s of slugs) {
    const h = page[s];
    assert.ok(h.includes(`<link rel="canonical" href="https://pointcast.xyz/coast-commons/${s}/">`), `${s} canonical`);
    assert.ok(h.includes('<meta name="author" content="Claude">'), `${s} byline`);
    assert.doesNotMatch(h, /<script[^>]+src=/i, `${s} loads no script file`);
    assert.doesNotMatch(h, /<img\b|<iframe\b|@import|@font-face|url\(http|fetch\(|XMLHttpRequest|sendBeacon|WebSocket|localStorage|document\.cookie/, `${s} makes no requests and stores nothing`);
    for (const m of h.matchAll(/<link[^>]+href="([^"]+)"/g)) assert.ok(m[1] === '/favicon.svg' || m[1] === '/coast-commons.json' || m[1] === `https://pointcast.xyz/coast-commons/${s}/`, `${s} link ${m[1]}`);
    assert.match(h, /<a class="skip" href="#main">/);
    assert.match(h, /<main id="main"/);
    assert.match(h, /<a href="\/coast-commons\/"><b>Coast Commons<\/b><\/a>/);
    assert.match(h, /Licence for the words and drawings: <a href="\/coast-commons\/LICENSE\.txt">CC BY 4\.0<\/a>/);
    assert.match(h, /chosen on November 12, 2026: anyone may reuse and adapt them with credit/);
  }
  assert.ok(existsSync(new URL('public/coast-commons/LICENSE.txt', root)), 'licence note');
  assert.ok(!existsSync(new URL('public/coast-commons-studies.json', root)), 'the studies live in /coast-commons.json, not a file of their own');
});

test('the hub, the JSON, the manifests and a sourced block all point at the studies', () => {
  for (const s of slugs) {
    assert.ok(hub.includes(`<a href="/coast-commons/${s}/">`), `hub links ${s}`);
    assert.ok(read('src/pages/sitemap-discovery.xml.ts').includes(`'https://pointcast.xyz/coast-commons/${s}/'`), `sitemap ${s}`);
    assert.ok(read('public/llms.txt').includes(`https://pointcast.xyz/coast-commons/${s}/`), `llms ${s}`);
    assert.ok(read('public/llms-full.txt').includes(`https://pointcast.xyz/coast-commons/${s}/`), `llms-full ${s}`);
    assert.ok(read('src/data/agent-surfaces.ts').includes(`'https://pointcast.xyz/coast-commons/${s}/'`), `agent surfaces ${s}`);
  }
  assert.deepEqual(twin.studies.list.map((x) => x.url), slugs.map((s) => `https://pointcast.xyz/coast-commons/${s}/`));
  assert.equal(twin.studies.licence.status, 'chosen');
  assert.equal(twin.studies.notice.length, NOTICE.length);
  const block = JSON.parse(read('src/content/blocks/0786.json'));
  assert.equal(block.author, 'cc');
  assert.ok(block.source.includes('November 11, 2026') && block.source.includes('none of it is in Mike\'s voice'));
  assert.equal(block.external.url, 'https://pointcast.xyz/coast-commons/sb-surf-house/');
  assert.equal(twin.studies.block, 'https://pointcast.xyz/b/0786');
  assert.doesNotMatch(read('public/_headers'), /coast-commons\/(sb-surf-house|fresh-milk)/, 'no _headers rule for these pages');
});
